/* Inventário de planejamento. Rotas propostas e exemplos não representam integrações. */
const chapters = ['Conta e entrada','Criar e entrar no Núcleo','Início e agenda','Acordos e consentimento','Árvore e memórias','Conexões e perfis','Manifesto e cuidado','Preferências e segurança'];
const screens = [];
const B = (type, title, text = '', to = 0) => ({type,title,text,to});
const field = (title,text='') => B('field',title,text);
const area = (title,text='') => B('area',title,text);
const card = (title,text='',to=0) => B('card',title,text,to);
const pick = (title,text) => B('pick',title,text);
const note = text => B('note','',text);
const tabs = text => B('tabs','',text);
const hero = (title,text) => B('hero',title,text);
// Cada destino é um ID estável do atlas, independente da numeração do protótipo antigo.
function S(id, chapter, title, subtitle, source, route, status, blocks, actions, rule, permission, dependency) {
  // As saídas de confirmação/recuperação voltam ao estado de login da mesma Tela 01.
  screens.push({id,chapter,title,subtitle,source,route,status,blocks,actions:actions.map(([label,to])=>({label,to,login:[3,4,5].includes(id)&&to===1})),rule,permission,dependency});
}
